#!/usr/bin/env python3
"""Regenerate the GitHub-safe, dependency-free neon command center graphics."""
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
A=ROOT/'assets'
def write(path,s):
 path.parent.mkdir(parents=True,exist_ok=True);path.write_text(s,encoding='utf-8')
common='''<defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#05090f"/><stop offset=".55" stop-color="#091b19"/><stop offset="1" stop-color="#06100e"/></linearGradient><linearGradient id="neon"><stop stop-color="#00f5a0"/><stop offset=".55" stop-color="#75ff9e"/><stop offset="1" stop-color="#00d9ff"/></linearGradient><radialGradient id="halo"><stop stop-color="#00ff9d" stop-opacity=".22"/><stop offset="1" stop-color="#00ff9d" stop-opacity="0"/></radialGradient><pattern id="grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#3be6b4" stroke-opacity=".075"/></pattern><filter id="glow"><feGaussianBlur stdDeviation="5"/></filter></defs>'''
hero=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="400" viewBox="0 0 1200 400" role="img" aria-labelledby="t d"><title id="t">Bhavish S — Cybersecurity command center</title><desc id="d">Futuristic emerald and cyan network security dashboard, orbiting radar and terminal typography</desc>{common}
<rect width="1200" height="400" rx="20" fill="url(#bg)"/><rect width="1200" height="400" rx="20" fill="url(#grid)"/><path d="M0 54H1200M0 345H1200" stroke="#2af7a4" stroke-opacity=".2"/>
<g font-family="monospace" fill="#65dcb3" font-size="13" letter-spacing="2"><text x="46" y="33">● SYSTEM ONLINE</text><text x="1150" y="33" text-anchor="end">SECURITY / ENGINEERING / AUTOMATION</text><text x="46" y="374">&gt; BUILD_SECURE // SHIP_BETTER</text><text x="1150" y="374" text-anchor="end">GITHUB.COM/BHAVISH-S</text></g>
<rect x="42" y="91" width="5" height="215" rx="2" fill="url(#neon)"/><text x="69" y="118" font-family="monospace" font-size="15" fill="#54eeb0" letter-spacing="3">WELCOME TO MY DIGITAL LAB</text><text x="62" y="203" font-family="Arial,Helvetica,sans-serif" font-size="81" font-weight="900" letter-spacing="-1" fill="#f1fff9">BHAVISH <tspan fill="url(#neon)">S.</tspan></text><text x="69" y="244" font-family="Arial,Helvetica,sans-serif" font-size="23" font-weight="700" fill="#c7e8df" letter-spacing="2">CYBERSECURITY  ×  FULL-STACK  ×  AUTOMATION</text><text x="69" y="281" font-family="monospace" font-size="15" fill="#7eb5a7">[ ETHICAL HACKING ]  [ SECURE SYSTEMS ]  [ CREATIVE CODE ]</text>
<circle cx="1003" cy="202" r="183" fill="url(#halo)"/><g transform="translate(1003 202)" fill="none" stroke="#25ed9b"><circle r="146" stroke-opacity=".25"/><circle r="112" stroke-opacity=".42" stroke-dasharray="6 9"/><circle r="78" stroke-opacity=".28"/><circle r="44" stroke-opacity=".6"/><path d="M-160 0H160M0 -160V160" stroke-opacity=".17"/><g><path d="M0 0L0 -142A142 142 0 0 1 142 0Z" fill="#00ff9d" fill-opacity=".08" stroke="none"/><path d="M0 0V-142" stroke="#7affbb" stroke-width="2"/><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="12s" repeatCount="indefinite"/></g><circle cx="-56" cy="-62" r="5" fill="#00ffc3"><animate attributeName="opacity" values="1;.25;1" dur="2s" repeatCount="indefinite"/></circle><circle cx="78" cy="48" r="4" fill="#00d9ff"/><circle cx="24" cy="-100" r="3" fill="#00ffc3"/></g><path d="M15 15H105M15 15V48M1185 15H1095M1185 15V48M15 385H105M15 385V352M1185 385H1095M1185 385V352" fill="none" stroke="#34ffb2" stroke-opacity=".6" stroke-width="2"/></svg>'''
write(A/'profile-header.svg',hero)
projects=[('nodue-portal','NODUE PORTAL','Student clearance workflow','React · TypeScript · Node.js · Firebase','DEPLOYED','01'),('budget-allocator','BUDGET ALLOCATOR','Smart budget planning & analytics','React · TypeScript','DEPLOYED','02'),('route-resilience','ROUTE RESILIENCE','Fault-tolerant network simulation','HTML · JavaScript · CSS','DEPLOYED','03'),('novic-events','NOVIC EVENTS','Event management & ticketing','Web Stack','DEPLOYED','04'),('siem-dashboard','SIEM DASHBOARD','Security event monitoring','Python · Elastic · Splunk · Kibana','IN DEV','05'),('pentest-toolkit','PENTEST TOOLKIT','Modular security testing automation','Python · Bash','IN DEV','06')]
for slug,name,desc,stack,status,num in projects:
 color='#5affb1' if status=='DEPLOYED' else '#f6c76a'
 s=f'''<svg xmlns="http://www.w3.org/2000/svg" width="580" height="250" viewBox="0 0 580 250" role="img" aria-labelledby="title desc"><title id="title">{escape(name)}</title><desc id="desc">{escape(desc)}; {escape(stack)}; {status}</desc>{common}<rect x="1" y="1" width="578" height="248" rx="18" fill="url(#bg)" stroke="#1c594a" stroke-width="2"/><rect x="2" y="2" width="576" height="246" rx="18" fill="url(#grid)"/><path d="M25 55H555M25 207H555" stroke="#317963" stroke-opacity=".5"/><text x="26" y="34" fill="#79cdb3" font-family="monospace" font-size="12" letter-spacing="2">PROJECT // {num}</text><rect x="449" y="17" width="106" height="24" rx="12" fill="{color}" fill-opacity=".12" stroke="{color}" stroke-opacity=".65"/><text x="502" y="33" fill="{color}" text-anchor="middle" font-family="monospace" font-size="11" font-weight="700">{status}</text><text x="26" y="105" fill="#f0fff9" font-family="Arial,Helvetica,sans-serif" font-size="29" font-weight="800">{escape(name)}</text><text x="27" y="139" fill="#a8d5c6" font-family="Arial,Helvetica,sans-serif" font-size="16">{escape(desc)}</text><text x="27" y="183" fill="#6affbb" font-family="monospace" font-size="13">{escape(stack)}</text><text x="27" y="232" fill="#699e90" font-family="monospace" font-size="11" letter-spacing="1">BHAVISH-S / FIELD OPERATIONS</text><path d="M520 83l15 15-15 15m15-15h-37" fill="none" stroke="#52ffc0" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="520" cy="157" r="40" fill="url(#halo)"/></svg>'''
 write(A/'projects'/f'{slug}.svg',s)
print('Regenerated hero and',len(projects),'project cards')
